/usr/bin/sh -c "python3 - <<'PY'
import os,json,hashlib
records={}
for d,dirs,files in os.walk('.',followlinks=False):
    dirs[:]=[x for x in dirs if x"'!='"'.git' and not os.path.islink(os.path.join(d,x))]
    if d"'!='"'.' and os.path.lexists(os.path.join(d,'.git')):
        dirs[:]=[]; continue
    for n in sorted(files):
        p=os.path.join(d,n)
        s=os.lstat(p)
        r={'size':s.st_size,'mtime':s.st_mtime_ns,'mode':s.st_mode,'inode':s.st_ino}
        if os.path.islink(p): r['link']=os.readlink(p)
        elif n not in ['.env','local.db','.npmrc','certificate.crt']: r['sha256']=hashlib.sha256(open(p,'rb').read()).hexdigest()
        records[p]=r
print(json.dumps(records,sort_keys=True))
PY"

